182	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
183	// only the built-in qemu descriptor, so it resolves that directly rather than
184	// discover_engines(), which would spawn a --describe subprocess per Verilator
185	// build only to discard them all here.
186	int run_fast(const Cli& cli) {
187	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
188	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
189	    std::fprintf(stderr,
190	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
191	                 "got '%s'\n",
192	                 cli.engine.c_str());
193	    return 2;
194	  }
195	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
196	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
197	  std::string err;
198	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
199	  if (!err.empty()) {
200	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
201	    return 2;
202	  }
203	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
204	  if (cli.gdb) {
205	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
206	    extra.push_back("-gdb");
207	    extra.push_back("tcp::" + port);
208	    extra.push_back("-S");
209	  }
210	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
211	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
212	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
213	  // ELF -- the override is the user's call.
214	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
215	  int xlen;
216	  if (cli.engine == kQemuId32) xlen = 32;
217	  else if (cli.engine == kQemuId64) xlen = 64;
218	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
219	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
220	  // == elf_w), so this guard already implies an explicit --engine.
221	  if (elf_w && elf_w != xlen)
222	    std::fprintf(stderr,
223	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
224	                 "(running as rv%d)\n",
225	                 cli.engine.c_str(), xlen, elf_w, xlen);
226	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
227	}
