// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7 lands the first standalone model, `fast` (QEMU
// alone, functional): resolve the built-in qemu engine, then hand off to
// transparent passthrough -- the ELF plus everything after `--` becomes the
// engine's own command line, run with inherited stdio, no timeout, and the
// exit code propagated, so a gdbstub / monitor / semihosting console all
// behave as if the engine were invoked directly. `cycle` (F8) and `hybrid`
// (F9) land in later features; their dispatch arms stub for now.
#include <cstdio>
#include <filesystem>
#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "process.hpp"
#include "run_passthrough.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
// success; on failure prints an error tagged with `ctx` and returns "". The
// existence check is here, at the shared resolver, so a missing path fails
// with a clear "ELF not found" instead of being handed to the engine (e.g.
// qemu's cryptic "Unable to find the RISC-V BIOS").
std::string abs_elf(const std::string& path, const std::string& ctx) {
  std::error_code ec;
  fs::path abs = fs::absolute(path, ec);
  if (ec) {
    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
                 ctx.c_str(), path.c_str());
    return "";
  }
  if (!fs::is_regular_file(abs, ec)) {
    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
                 path.c_str());
    return "";
  }
  return abs.string();
}

// Validate the lone-ELF positional shape the standalone models require: print
// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
int check_one_elf(const Cli& cli, const char* model) {
  if (cli.positional.empty()) {
    std::fprintf(stderr,
                 "andesim run --mode %s: missing ELF (the workload to run; "
                 "e.g. a tests/fixtures/<name>.elf)\n",
                 model);
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andesim run --mode %s: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 model, cli.positional[1].c_str());
    return 2;
  }
  return 0;
}

// The standalone spine: take a single ELF, then run the resolved engine
// standalone with the post-`--` args appended verbatim (exec_passthrough --
// inherit stdio, no timeout, propagate the exit code, so an interactive
// gdbstub / monitor / semihosting console works unchanged). The per-model
// engine + selection are resolved by the caller; `model` here only labels
// the positional diagnostics.
int run_standalone(const Cli& cli, const EngineDescriptor& eng,
                   const char* model) {
  if (int rc = check_one_elf(cli, model)) return rc;
  // QEMU's -bios flag searches its data directory for relative paths rather
  // than the CWD; resolve to absolute so the engine finds the ELF.
  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
  if (elf.empty()) return 2;
  std::string err;
  const std::vector<std::string> argv =
      passthrough_argv(eng, "standalone", elf, cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
    return 2;
  }
  return exec_passthrough(argv);
}

// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
// only the built-in qemu descriptor, so it resolves that directly rather than
// discover_engines(), which would spawn a --describe subprocess per Verilator
// build only to discard them all here.
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != kQemuId) {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  return run_standalone(cli, builtin_qemu(), "fast");
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);

  std::fprintf(stderr, "andesim run --mode %s: not yet implemented\n",
               cli.model.c_str());
  return 3;
}

}  // namespace andes_sim

