  // --- stage_qemu_cfg: a clean probe writes the cfg; a failed probe falls back ---
  // The accurate engine's `--print-qemu-config` stdout becomes workdir/qemu.cfg;
  // any probe failure (engine lacks the flag -> non-zero exit, timeout, empty)
  // yields "" so the fast leg keeps its default -cpu.
  {
    namespace fs = std::filesystem;
    const fs::path dir = fs::temp_directory_path() / "andesim-fa2-stage";
    fs::remove_all(dir);
    fs::create_directories(dir);

    RunResult ok;
    ok.rc = 0;
    ok.out = "[global]\ndriver = \"andes-ax45mpv-riscv-cpu\"\nproperty = \"v\"\n";
    const std::string p = stage_qemu_cfg(dir.string(), ok);
    CHECK(p == (dir / "qemu.cfg").string());
    {
      std::ifstream f(p);
      const std::string c((std::istreambuf_iterator<char>(f)),
                          std::istreambuf_iterator<char>());
      CHECK(c == ok.out);
    }

    RunResult unknown_flag;  // engine without --print-qemu-config: parser throws
    unknown_flag.rc = 1;
    unknown_flag.out = "Unrecognized option: --print-qemu-config\n";
    CHECK(stage_qemu_cfg(dir.string(), unknown_flag).empty());

    RunResult timed_out;
    timed_out.timed_out = true;
    CHECK(stage_qemu_cfg(dir.string(), timed_out).empty());

    RunResult empty_out;  // exit 0 but nothing emitted -> nothing to load
    empty_out.rc = 0;
    CHECK(stage_qemu_cfg(dir.string(), empty_out).empty());

    fs::remove_all(dir);
  }

  // --- plan_argvs: a QEMU readconfig cfg is injected into the fast leg only ---
  // The engine's config.inc, distilled to a QEMU `-readconfig` cfg, makes the
  // QEMU producer match the accurate engine's ISA. Only the fast (QEMU) leg
  // gets `-readconfig <cfg>`; the vsim accurate leg never does. An empty cfg
  // injects nothing (fallback to the descriptor's default -cpu).
  {
    RuntimeCtx rcfg = rc;
    rcfg.qemu_cfg = "/wd/qemu.cfg";
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rcfg, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      bool fast_has = false;
      for (size_t k = 0; k + 1 < argvs[0].size(); ++k)
        if (argvs[0][k] == "-readconfig" && argvs[0][k + 1] == "/wd/qemu.cfg")
          fast_has = true;
      CHECK(fast_has);
      for (const std::string& a : argvs[1]) CHECK(a != "-readconfig");
    }
  }
  // empty qemu_cfg (the default rc) injects no -readconfig on either leg
  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    if (argvs.size() == 2)
      for (const std::vector<std::string>& a : argvs)
        for (const std::string& tok : a) CHECK(tok != "-readconfig");
  }

  // --- leg_trigger_args: a trigger's per-role argv contribution ---
  {
    std::string err;
    // marker drives nothing into the argv; the plugin/vsim detect markers.
    LegTriggerArgs marker = leg_trigger_args({"marker", {}}, "fast-leg", err);
    CHECK(err.empty());
    CHECK(marker.plugin_suffix.empty());
    CHECK(marker.extra.empty());

    // pc: qemu gets the enter_pc plugin suffix; vsim gets the exit-pc tokens.
    const Trigger pc = {"pc", {{"enter_pc", "0x10"}, {"exit_pc", "0x20"}}};
    LegTriggerArgs pf = leg_trigger_args(pc, "fast-leg", err);
    CHECK(err.empty());
    CHECK(pf.plugin_suffix == ",enter_pc=0x10");
    CHECK(pf.extra.empty());
    LegTriggerArgs pa = leg_trigger_args(pc, "accurate-leg", err);
    CHECK(err.empty());
    CHECK(pa.plugin_suffix.empty());
    check_eq(pa.extra, {"--hybrid-exit-pc", "0x20"}, "pc-acc");

    // a role outside fast-leg/accurate-leg carries no trigger args
    LegTriggerArgs none = leg_trigger_args(pc, "standalone", err);
    CHECK(err.empty());
    CHECK(none.plugin_suffix.empty());
    CHECK(none.extra.empty());

    // unknown trigger kind / missing required param are errors
    leg_trigger_args({"bogus", {}}, "fast-leg", err);
    CHECK(!err.empty());
    leg_trigger_args({"pc", {}}, "fast-leg", err);
    CHECK(!err.empty());

    // verify oracle leg (verify_oracle F4): qemu drains at the ROI exit,
    // sampling at vsim's drained pc (drain_pc).
    const Trigger vm = {"verify-marker", {{"drain_pc", "0x100072"}}};
    LegTriggerArgs vmf = leg_trigger_args(vm, "fast-leg", err);
    CHECK(err.empty());
    CHECK(vmf.plugin_suffix == ",exit_marker=1,drain_pc=0x100072");
    CHECK(vmf.extra.empty());
    const Trigger vp = {"verify-pc",
                        {{"exit_pc", "0x20"}, {"drain_pc", "0x28"}}};
    LegTriggerArgs vpf = leg_trigger_args(vp, "fast-leg", err);
    CHECK(err.empty());
    CHECK(vpf.plugin_suffix == ",exit_pc=0x20,drain_pc=0x28");
    leg_trigger_args({"verify-marker", {}}, "fast-leg", err);
    CHECK(!err.empty());  // missing drain_pc
    leg_trigger_args({"verify-pc", {{"drain_pc", "0x28"}}}, "fast-leg", err);
    CHECK(!err.empty());  // missing exit_pc
  }

  // --- plan_argvs: pc trigger threads enter_pc (qemu) + exit_pc (vsim) ---
  {
    Plan p = plan;
    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
    p.steps[0].trigger = pc;
    p.steps[1].trigger = pc;
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(p, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // qemu: enter_pc folded into the single -plugin token (its last arg)
      CHECK(argvs[0].back() == "/pl,outfile=/wd/state-0.bin,enter_pc=0x100000");
      // vsim: --hybrid-exit-pc appended verbatim after the filled template
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0",
                "--hybrid-exit-pc", "0x100042"},
               "pc-step1");
    }
  }

  // --- plan_argvs: Step.extra_args append AFTER trigger args (e2e.sh order) ---
  {
    Plan p = plan;
    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
    p.steps[0].trigger = pc;
    p.steps[1].trigger = pc;
    p.steps[1].extra_args = {"--kanata", "k.txt"};
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(p, engines, "/wd", rc, err);
    CHECK(err.empty());
    if (argvs.size() == 2) {
      const std::vector<std::string>& v = argvs[1];
      CHECK(v.size() >= 4);
      // tail order: ... --hybrid-exit-pc 0x100042 --kanata k.txt
      CHECK(v[v.size() - 4] == "--hybrid-exit-pc");
      CHECK(v[v.size() - 3] == "0x100042");
      CHECK(v[v.size() - 2] == "--kanata");
      CHECK(v.back() == "k.txt");
    }
  }

  // unknown engine id is an error
  {
    Plan bad = plan;
    bad.steps[0].engine_id = "nope";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }
  // a role the engine has no template for is an error
  {
    Plan bad = plan;
    bad.steps[1].role = "no-such-role";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }

  // plan_step_rc_error: a drain leg that exits 0 ran the workload to completion
  // without ever reaching its ROI boundary -- the trigger never fired. The
  // message must say so and name the trigger kind, not just the bare
  // "expected exit 200, got 0" the user cannot act on.
  {
    const Step s{"qemu", "fast-leg", {"marker", {}}};
    const std::string m = plan_step_rc_error(0, s, 200, 0);
    CHECK(m.find("plan step 0") != std::string::npos);
    CHECK(m.find("marker") != std::string::npos);
    CHECK(m.find("without reaching") != std::string::npos);
  }
  // a genuine non-zero failure (engine crash, not a clean completion) keeps the
  // bare line -- no false "trigger never fired" claim.
  {
    const Step s{"qemu", "fast-leg", {"marker", {}}};
    const std::string m = plan_step_rc_error(1, s, 200, 139);
    CHECK(m.find("expected exit 200, got 139") != std::string::npos);
    CHECK(m.find("without reaching") == std::string::npos);
  }

  return andes_sim::test::report("plan");
}

===== F5-F6 (5b6efed) driver/plan.hpp =====
// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
//
// A Plan is a list of Steps; each Step names an engine (by id, resolved against
// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
// order, threads the drained hybrid_state_v1 file forward, and returns each
// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
// mcycle.
#ifndef ANDES_SIM_PLAN_HPP
#define ANDES_SIM_PLAN_HPP

#include <map>
#include <string>
#include <vector>

namespace andes_sim {

// The ROI delimiter for a step. `kind` is csr|pc|icount|simpoint; `params`
// carries kind-specific values (e.g. icount=N, enter_pc, exit_pc) that F9 maps
// onto trigger args. F6 only exercises the default csr case (no params).
struct Trigger {
  std::string kind;
  std::map<std::string, std::string> params;
};

// One leg of a plan: which engine, which invoke role, under which trigger.
struct Step {
  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
  Trigger trigger;
};

// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
// every leg so memory threads through.
struct Plan {
  std::string elf;          // path to the ELF every leg launches
  long long mem_size = 0;   // shared-mmap size in bytes
  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
  std::vector<Step> steps;
};

// What one drain step measured (read back from its state file).
struct PhaseResult {
  unsigned long long mcycle = 0;
  unsigned long long minstret = 0;
};

// Aggregate outcome. `error` empty => every step matched its expected exit and
// drained a valid state file; `phases` then holds one entry per step in order.
struct PlanResult {
  std::string error;
  std::vector<PhaseResult> phases;
  bool ok() const { return error.empty(); }
};

}  // namespace andes_sim

#endif  // ANDES_SIM_PLAN_HPP

===== F5-F6 (5b6efed) driver/run_plan.hpp =====
// The phase-plan executor (F6) -- the C++ analog of runner.run_session, minus
// the dropped QEMU2 handback. run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDES_SIM_RUN_PLAN_HPP
#define ANDES_SIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
};

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = 200;        // drain success code (kExitHandoffToQemu)
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
};

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDES_SIM_RUN_PLAN_HPP

===== F5-F6 (5b6efed) driver/run_plan.cpp =====
// The phase-plan executor. See run_plan.hpp.
#include "run_plan.hpp"

#include <cstdlib>
#include <filesystem>

#include <unistd.h>

#include "argv.hpp"
#include "process.hpp"
#include "repo_root.hpp"
#include "shm.hpp"
#include "state.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
std::string state_path(const std::string& workdir, size_t i) {
  return workdir + "/state-" + std::to_string(i) + ".bin";
}

const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
                                    const std::string& id) {
  for (const EngineDescriptor& e : engines)
    if (e.id == id) return &e;
  return nullptr;
}

// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
std::string resolve_plugin(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
  return default_plugin_path().string();
}

}  // namespace

std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
  std::vector<std::vector<std::string>> out;
  out.reserve(plan.steps.size());
  std::string prev_state_out;  // empty for the cold first leg

  for (size_t i = 0; i < plan.steps.size(); ++i) {
    const Step& step = plan.steps[i];
    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
    if (!eng) {
      err = "plan step " + std::to_string(i) + ": unknown engine '" +
            step.engine_id + "'";
      return {};
    }
    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
    if (!tmpl) {
      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
            "' has no invoke template for role '" + step.role + "'";
      return {};
    }

    const std::string state_out = state_path(workdir, i);
    const std::map<std::string, std::string> m = {
        {"bin", eng->bin_path},
        {"elf", plan.elf},
        {"plugin", ctx.plugin_path},
        {"mmap", ctx.mmap_path},
        {"mmap_size", std::to_string(ctx.mem_size)},
        {"mmap_base", ctx.mmap_base},
        {"state_in", prev_state_out},
        {"state_out", state_out},
    };
    std::vector<std::string> argv = build_argv(*tmpl, m, err);
    if (!err.empty()) {
      err = "plan step " + std::to_string(i) + ": " + err;
      return {};
    }
    out.push_back(std::move(argv));
    prev_state_out = state_out;
  }
  err.clear();
  return out;
}

PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts) {
  PlanResult res;
  if (plan.steps.empty()) {
    res.error = "plan has no steps";
    return res;
  }

  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
  std::string mmap_path = plan.mmap_path;
  const bool own_mmap = mmap_path.empty();
  if (own_mmap) {
    std::string err;
    mmap_path = allocate(plan.mem_size, err);
    if (mmap_path.empty()) {
      res.error = err;
      return res;
    }
  }

  // A private dir for the threaded drain files.
  std::error_code ec;
  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
  std::string tmpl = workdir.string();
  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
  tbuf.push_back('\0');
  const char* made = ::mkdtemp(tbuf.data());
  if (!made) {
    if (own_mmap) ::unlink(mmap_path.c_str());
    res.error = "failed to create plan work dir";
    return res;
  }
  const std::string wd = made;

  RuntimeCtx ctx;
  ctx.mmap_path = mmap_path;
  ctx.mem_size = plan.mem_size;
  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default

  std::string err;
  const std::vector<std::vector<std::string>> argvs =
      plan_argvs(plan, engines, wd, ctx, err);
  if (!err.empty()) {
    res.error = err;
  } else {
    for (size_t i = 0; i < argvs.size(); ++i) {
      const RunResult r = run_process(argvs[i], opts.timeout_ms);
      if (r.spawn_failed) {
        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
        break;
      }
      if (r.timed_out) {
        res.error = "plan step " + std::to_string(i) + ": timed out after " +
                    std::to_string(opts.timeout_ms) + " ms";
        break;
      }
      if (r.rc != opts.expect_rc) {
        res.error = "plan step " + std::to_string(i) + ": expected exit " +
                    std::to_string(opts.expect_rc) + ", got " +
                    std::to_string(r.rc);
        break;
      }
      const StateFile sf = read_state_file(state_path(wd, i));
      if (!sf.ok()) {
        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
        break;
      }
      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
    }
  }

  fs::remove_all(wd, ec);
  if (own_mmap) ::unlink(mmap_path.c_str());
  return res;
}

}  // namespace andes_sim

===== F5-F6 (5b6efed) driver/plan_test.cpp =====
// Unit tests for the F6 phase-plan executor's pure core:
//   - build_argv  (driver/argv.hpp)     invoke-template placeholder fill
//   - plan_argvs  (driver/run_plan.hpp) state-file threading across steps
//
// These cover everything in run_plan EXCEPT the live spawn loop, which the
// integration acceptance (tests/andes_sim/test_andes_sim_f6.sh -> a real
// 2-step qemu+vsim run) exercises. Plain assert-and-count harness; run by that
// same f6 script. No QEMU2 leg exists -- handback was removed.
#include <map>
#include <string>
#include <vector>

#include "argv.hpp"
#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "run_plan.hpp"
#include "test_check.hpp"

using namespace andes_sim;

namespace {

// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
const std::vector<std::string> kQemuFastLeg = {
    "{bin}",
    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
    "-machine", "andes_ae350,memory-backend=mem",
    "-cpu", "andes-ax45mpv,vlen=512",
    "-nographic",
    "-semihosting-config", "enable=on,target=native",
    "-bios", "{elf}",
    "-plugin", "{plugin},outfile={state_out}",
};

const std::vector<std::string> kVsimAccurateLeg = {
    "{bin}", "{elf}",
    "--resume-from-qemu", "{state_in}",
    "--handoff-out", "{state_out}",
    "--shared-mem-path", "{mmap}",
    "--shared-mem-size", "{mmap_size}",
    "--shared-mem-base", "{mmap_base}",
};

EngineDescriptor fake(const std::string& id, const std::string& bin,
                      const std::string& role,
                      const std::vector<std::string>& tmpl) {
  EngineDescriptor d;
  d.id = id;
  d.bin_path = bin;
  d.invoke.push_back({role, tmpl});
  return d;
}

void check_eq(const std::vector<std::string>& got,
              const std::vector<std::string>& want, const char* label) {
  CHECK(got.size() == want.size());
  const size_t n = got.size() < want.size() ? got.size() : want.size();
  for (size_t i = 0; i < n; ++i) {
    if (got[i] != want[i])
      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
                   got[i].c_str(), want[i].c_str());
    CHECK(got[i] == want[i]);
  }
}

}  // namespace

int main() {
  // --- build_argv: every placeholder filled, including substring + repeat ---
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
    };
    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-object",
              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
              "enable=on,target=native", "-bios", "/e", "-plugin",
              "/p,outfile=/s0"},
             "qemu");
  }
  {
    std::string err;
    std::map<std::string, std::string> ctx = {
        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
        {"mmap_base", "0x0"},
    };
    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
    CHECK(err.empty());
    check_eq(got,
             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
              "--shared-mem-base", "0x0"},
             "vsim");
  }
  // a repeated placeholder expands every occurrence
  {
    std::string err;
    std::vector<std::string> got =
        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
    CHECK(err.empty());
    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
  }
  // an unknown placeholder is an error, not a silent empty fill
  {
    std::string err;
    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
  std::vector<EngineDescriptor> engines = {
      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
      fake("verilator:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
  };
  Plan plan;
  plan.elf = "/e";
  plan.mem_size = 134217728;
  plan.steps = {
      {"qemu", "fast-leg", {"csr", {}}},
      {"verilator:test", "accurate-leg", {"csr", {}}},
  };
  RuntimeCtx rc;
  rc.mmap_path = "/mm";
  rc.mem_size = 134217728;
  rc.mmap_base = "0x0";
  rc.plugin_path = "/pl";

  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // step 0 (qemu): drains to state-0.bin; no state_in referenced
      check_eq(argvs[0],
               {"/qbin", "-object",
                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
                "enable=on,target=native", "-bios", "/e", "-plugin",
                "/pl,outfile=/wd/state-0.bin"},
               "step0");
      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
               "step1");
    }
  }
  // unknown engine id is an error
  {
    Plan bad = plan;
    bad.steps[0].engine_id = "nope";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }
  // a role the engine has no template for is an error
  {
    Plan bad = plan;
    bad.steps[1].role = "no-such-role";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }

  return andes_sim::test::report("plan");
}

