EngineDescriptor builtin_qemu() {
  EngineDescriptor d;
  d.id = kQemuId;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = 64;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone", "fast-leg"};
  // The hybrid fast-forward leg: load the ELF, drain on the plugin's trigger
  // into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out} are
  // filled by the plan executor (F6); {trigger} is the plugin comma-suffix
  // (empty for marker), folded by leg_trigger_args (F9).
  d.invoke.push_back(
      {"fast-leg",
       {"{bin}", "-object",
        "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
        "-machine", "andes_ae350,memory-backend=mem", "-cpu",
        "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
        "enable=on,target=native", "-bios", "{elf}", "-plugin",
        "{plugin},outfile={state_out}{trigger}"}});

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs C-runtime fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv. We pass NO vlen -- the cpu model's own QEMU
  // default applies, so both scalar and vector binaries run out of the box; a
  // user who needs a specific width passes it via the post-`--` -cpu (e.g.
  // -cpu andes-ax46mpv,vlen=512), which still wins. run_passthrough fills
  // {bin}/{elf}.
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax46mpv",
        "-nographic", "-semihosting-config", "enable=on,target=native",
        "-bios", "{elf}"}});

  if (const char* q = std::getenv("VSIM_QEMU"); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / "qemu-system-riscv64").string();
  else
    d.bin_path =
        (repo_root() / "build" / "qemu" / "qemu-system-riscv64").string();
  return d;
}
  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
  }
  return out;
}

=== c11 models.hpp ===
// The three models andesim composes from engines. A model says *which*
// engines run and *how* they combine; the concrete engine(s) are resolved
// separately (built-in qemu, or a discovered verilator:<cfg>).
//
//   fast      = QEMU alone (functional), transparent passthrough.
//   cycle     = one Verilator alone, pure from reset, transparent passthrough.
//   hybrid    = QEMU fast-forwards, Verilator measures the ROI (+ a trigger).
#ifndef ANDESIM_MODELS_HPP
#define ANDESIM_MODELS_HPP

#include <string_view>

namespace andes_sim {

struct Model {
  std::string_view name;
  std::string_view engines;  // engine composition, for `list models`
  std::string_view notes;
};

inline constexpr Model kModels[] = {
    {"fast", "qemu", "functional"},
    {"cycle", "vsim:<cfg>", "cycle-accurate"},
    {"hybrid", "qemu -> vsim",
     "QEMU fast-forwards, vsim measures the ROI; "
     "pick --trigger marker|pc"},
};

inline const Model* find_model(std::string_view name) {
  for (const Model& m : kModels)
    if (m.name == name) return &m;
  return nullptr;
}

}  // namespace andes_sim

#endif  // ANDESIM_MODELS_HPP

